.watch-skeleton #primary-info .menu-button { height: 20px; width: 20px; border-radius: 50%; margin-left: 20px; }
.watch-skeleton #bottom-row .menu-button { height: 36px; width: 36px; border-radius: 50%; margin-left: 20px; }
.watch-skeleton #secondary-info { height: 151px; margin-bottom: 24px; padding: 16px 0px; }
.watch-skeleton #secondary-info #top-row, .watch-skeleton #secondary-info #top-row #video-owner { display: flex; -webkit-box-orient: horizontal; -webkit-box-direction: normal; flex-direction: row; }
.watch-skeleton #secondary-info #top-row #video-owner #channel-icon { height: 48px; width: 48px; border-radius: 50%; margin-right: 16px; }
.watch-skeleton #secondary-info #top-row #video-owner #upload-info { display: flex; -webkit-box-orient: vertical; -webkit-box-direction: normal; flex-direction: column; -webkit-box-pack: center; justify-content: center; }
.watch-skeleton #secondary-info #top-row #video-owner #upload-info #owner-name { width: 200px; margin-bottom: 12px; }
.watch-skeleton #secondary-info #top-row #video-owner #upload-info #published-date { width: 200px; }
.watch-skeleton #secondary-info #top-row #subscribe-button { width: 137px; height: 36px; border-radius: 8px; margin: 7px 4px 0px 0px; }
#watch-page-skeleton #related { float: right; position: relative; clear: right; max-width: 426px; width: calc(100% - 640px); }
#watch-page-skeleton #side-info-container { float: right; display: flex; position: absolute; -webkit-box-orient: vertical; -webkit-box-direction: normal; flex-direction: column; clear: right; max-width: 426px; right: 16px; top: 56px; width: calc(100% - 672px); }
#watch-page-skeleton #side-info-container.theater { position: relative; right: 16px; }
#watch-page-skeleton.theater #related { width: 100%; }
.watch-skeleton #related .autoplay { margin-bottom: 16px; }
.watch-skeleton #related[playlist] .autoplay { border-bottom: none; margin-bottom: 0px; }
.watch-skeleton #related #upnext { height: 20px; width: 120px; margin-bottom: 14px; }
.watch-skeleton #related[playlist] #upnext { display: none; }
.watch-skeleton #related .video-details { display: flex; -webkit-box-orient: horizontal; -webkit-box-direction: normal; flex-direction: row; padding-bottom: 8px; }
.watch-skeleton #related:not([playlist]) .autoplay .video-details { padding-bottom: 16px; }
.watch-skeleton #related .video-details .thumbnail { height: 94px; width: 168px; margin-right: 8px; }
.watch-skeleton #related .video-details .video-title { width: 200px; margin-bottom: 12px; }
.watch-skeleton #related .video-details .video-meta { width: 120px; }
@media (max-width: 999px) {
  #watch-page-skeleton { width: 854px; }
  #watch-page-skeleton #container { display: flex; -webkit-box-orient: vertical; -webkit-box-direction: normal; flex-direction: column; }
  #watch-page-skeleton #info-container { -webkit-box-ordinal-group: 2; order: 1; }
  #watch-page-skeleton #grid-container-skeleton { -webkit-box-ordinal-group: 2; order: 1; width: calc(-474px + 100vw); }
  #watch-page-skeleton #related { -webkit-box-ordinal-group: 3; order: 2; width: 100%; max-width: 100%; }
}
@media (max-width: 856px) {
  #watch-page-skeleton { width: 640px; }
}
@media (max-width: 656px) {
  #watch-page-skeleton { width: 426px; }
}
@media (min-width: 882px) {
  #watch-page-skeleton.theater { width: 100%; max-width: 1706px; padding: 0px 32px; }
  #watch-page-skeleton.theater #related { margin-top: 0px; }
  #watch-page-skeleton.theater #info-container > * { margin-right: 24px; }
}
@media (min-width: 1000px) {
  #watch-page-skeleton { width: 100%; max-width: 1066px; }
  #watch-page-skeleton #related { margin-top: -360px; padding-left: 24px; }
  #watch-page-skeleton #info-container { width: 640px; }
  #watch-page-skeleton.theater #info-container { width: 100%; padding-right: 426px; }
}
@media (min-width: 1294px) and (min-height: 630px) {
  #watch-page-skeleton { width: 100%; max-width: 1280px; }
  #watch-page-skeleton #related { margin-top: -480px; }
  #watch-page-skeleton #info-container { width: 854px; }
}
@media (min-width: 1720px) and (min-height: 980px) {
  #watch-page-skeleton { width: 100%; max-width: 1706px; }
  #watch-page-skeleton #related { margin-top: -720px; }
  #watch-page-skeleton #info-container { width: 1280px; }
}
#watch-page-skeleton.theater.theater-all-widths { width: 100%; max-width: 1706px; padding: 0px 32px; }
#watch-page-skeleton.theater.theater-all-widths #related { margin-top: 0px; }
#watch-page-skeleton.theater.theater-all-widths #info-container > * { margin-right: 24px; }
#watch-page-skeleton #related { display: none; }
